			function onBtn3Click2(e){
			    var btn3 = e.control;
			    
			    var dsList = app.lookup("dsList")
			    
			    var flag = true;
			    for (var i=0; i < dsList.getRowCount(); i++) {
			        
			        var rowData = dsList.getRowData(i);
			        
			        if (rowData["성명"] == null || rowData["성명"].trim() == "") {
			            util.Msg.alert(app, "성명은 필수 입력사항입니다.");
			            flag = false;
			            break;

			        } else if (rowData["사용자구분"] == null || rowData["사용자구분"].trim() == "") {
			            util.Msg.alert(app, "사용자구분 값은 필수 입력사항입니다.");
			            flag = false;
			            break;
			            
			        } else if (rowData["사용자구분"].length > 33) {
			            util.Msg.alert(app, "사용자구분 값은 100 byte (한글 33자)를 초과할 수 없습니다.\n- " + rowData["사용자구분"]);
			            flag = false;
			            break;
			        }
			        
			        if (rowData["휴대전화번호"] != null && rowData["휴대전화번호"].substring(0, 2) == "10") {
			            dsList.setValue(i, "휴대전화번호", "0" + rowData["휴대전화번호"]);
			        }
			    }
			    
			    if (flag) {
			        app.getHost().returnValue = dsList;  
			        
			        app.close();
			    }
			}

